<script>
(()=>{'use strict';const page=document.getElementById('ce-page'),form=document.getElementById('ce-form'),nav=document.getElementById('ce-tabs');const tabs=[...nav.querySelectorAll('button')];
function activate(key,focus=false){tabs.forEach(t=>{const active=t.dataset.panel===key;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById('ce-panel-'+t.dataset.panel).hidden=!active;if(active&&focus)t.focus();});}
nav.setAttribute('role','tablist');tabs.forEach((t,i)=>{t.setAttribute('role','tab');t.setAttribute('aria-controls','ce-panel-'+t.dataset.panel);const p=document.getElementById('ce-panel-'+t.dataset.panel);p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',t.id);t.addEventListener('click',()=>activate(t.dataset.panel));t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();activate(tabs[n].dataset.panel,true);}});});page.classList.add('enhanced');nav.hidden=false;activate('info');
form.addEventListener('invalid',e=>{const panel=e.target.closest('.ce-panel');if(panel)activate(panel.id.replace('ce-panel-',''));},true);
const bindings={name:['ce-title','Votre prochain grand titre'],plot:['ce-plot','Ajoutez un synopsis pour donner vie à cette fiche.'],release_date:['ce-date','Date à renseigner'],runtime:['ce-runtime','Durée à renseigner'],rating:['ce-rating','Non noté'],director:['ce-director','À renseigner'],genre:['ce-genre','À renseigner']};
const poster=document.getElementById('ce-poster'),placeholder=document.getElementById('ce-placeholder');let timer;
function updatePoster(){poster.hidden=true;placeholder.hidden=false;const raw=form.elements.icon.value.trim();try{const url=new URL(raw);if(!['http:','https:'].includes(url.protocol))throw new Error('protocol');poster.src=url.href;}catch(_){poster.removeAttribute('src');}}
poster.addEventListener('load',()=>{poster.hidden=false;placeholder.hidden=true;});poster.addEventListener('error',()=>{poster.hidden=true;placeholder.hidden=false;});updatePoster();
form.addEventListener('input',e=>{const name=e.target.name;if(bindings[name]){const [id,fallback]=bindings[name];document.getElementById(id).textContent=e.target.value.trim()||fallback;}if(name==='visible')document.getElementById('ce-status').textContent=e.target.checked?'Visible':'Masqué';if(name==='icon'){clearTimeout(timer);timer=setTimeout(updatePoster,350);}document.getElementById('ce-edit-status').textContent='Modifications non enregistrées';});
})();
</script>
